param([string] $filePath)\$content = Get-Content -Path \$filePath -Encoding UTF8\n\$old = "stmt = select(MemoryRecord).where(MemoryRecord.user_id == user_id)"\n\$new = "stmt = select(MemoryRecord).where(MemoryRecord.user_id == user_id)\\n            # Build filter with user_id clause for multi-tenant isolation (H2)\\n            filter_dict = self._build_filter(user_id)"\nif (\$content -contains \$old) {\n    \$content = \$content -replace [regex]::Escape(\$old), \$new\n    \$content | Set-Content -Path \$filePath -Encoding UTF8\n    Write-Host "SUCCESS: Modified \$filePath"\n} else {\n    Write-Host "Pattern not found in \$filePath"\n}
